import java.io.InputStream;
import java.lang.reflect.*;
import java.sql.*;
import java.util.*;
import restaurante.modelo.*;
import restaurante.dao.mysql.VentaDAOMySQL;
import restaurante.repositorio.PedidoRepositorio;
import patrones.command.ConfirmarPedidoComando;
import net.sf.jasperreports.engine.*;
import net.sf.jasperreports.engine.data.JRMapCollectionDataSource;

public class VerificaRestaurante {
 static boolean fallo,commit,rollback,autoOff; static List<String> sqls;
 static Object def(Class<?> t){if(!t.isPrimitive())return null;if(t==boolean.class)return false;if(t==int.class)return 0;if(t==long.class)return 0L;if(t==double.class)return 0d;if(t==float.class)return 0f;return null;}
 @SuppressWarnings("unchecked") static <T>T p(Class<T> t,InvocationHandler h){return(T)Proxy.newProxyInstance(t.getClassLoader(),new Class<?>[]{t},h);}
 static ResultSet row(boolean has,Object...v){final int[] n={0};return p(ResultSet.class,(o,m,a)->{switch(m.getName()){case "next":return has&&n[0]++==0;case "getString":return String.valueOf(v[(Integer)a[0]-1]);case "getInt":return ((Number)v[(Integer)a[0]-1]).intValue();default:return def(m.getReturnType());}});}
 static Connection conn(){return p(Connection.class,(o,m,a)->{switch(m.getName()){
 case "setAutoCommit": autoOff=Boolean.FALSE.equals(a[0]);return null; case "commit":commit=true;return null;case "rollback":rollback=true;return null;
 case "prepareStatement":{String sql=(String)a[0];sqls.add(sql);return p(PreparedStatement.class,(x,k,b)->{if(k.getName().equals("executeQuery")){if(sql.startsWith("SELECT estado"))return row(true,"En preparacion",1);if(sql.startsWith("SELECT id_pago"))return row(false);if(sql.startsWith("SELECT d.id_detalle"))return row(true,1,1);throw new SQLException("Consulta inesperada "+sql);}if(k.getName().equals("executeUpdate")){if(fallo&&sql.startsWith("INSERT INTO pedido_eventos"))throw new SQLException("Fallo de auditoría simulado");return 1;}if(k.getName().equals("getGeneratedKeys"))return row(true,77);return def(k.getReturnType());});}
 default:return def(m.getReturnType());}});}
 static class DriverFalso implements Driver{public Connection connect(String u,Properties p){return conn();}public boolean acceptsURL(String u){return u.startsWith("jdbc:mysql:");}public DriverPropertyInfo[] getPropertyInfo(String u,Properties p){return new DriverPropertyInfo[0];}public int getMajorVersion(){return 1;}public int getMinorVersion(){return 0;}public boolean jdbcCompliant(){return false;}public java.util.logging.Logger getParentLogger(){return java.util.logging.Logger.getGlobal();}}
 static void venta(boolean falla){fallo=falla;commit=false;rollback=false;autoOff=false;sqls=new ArrayList<>();Pedido pedido=new Pedido("T-01");pedido.setIdPedido(1);pedido.setEstado("En preparacion");Venta v=new Venta(0,pedido,MetodoPago.EFECTIVO,10,0,1.8,11.8);try{new VentaDAOMySQL().guardar(v);if(falla)throw new AssertionError("Debió fallar");}catch(IllegalArgumentException ex){if(!falla)throw ex;}if(!autoOff||commit==falla||rollback!=falla||v.getIdVenta()!=(falla?0:77))throw new AssertionError("Transacción incorrecta");if(!falla){String todo=String.join(" ",sqls).toLowerCase();for(String t:new String[]{"pedidos","detalle_pedido","productos","pagos","pedido_eventos","mesas"})if(!todo.contains(t))throw new AssertionError("Falta tabla "+t);}System.out.println(falla?"OK: fallo de auditoría provoca rollback sin commit":"OK: commit con seis tablas participantes");}
 static void patrones(){Pedido pedido=new Pedido("T");pedido.agregarDetalle(1,"Uno",2,3.50);pedido.agregarDetalle(2,"Dos",1,2.0);if(Math.abs(pedido.calcularTotal()-9)>0.001)throw new AssertionError("Composite");PedidoRepositorio repo=new PedidoRepositorio(){public void guardar(Pedido x){throw new IllegalArgumentException("fallo simulado");}public Pedido buscarPorCodigo(String c){return null;}public List<Pedido> listar(){return Collections.emptyList();}public boolean eliminar(String c){return false;}public void actualizarEstado(int id,String e){}};try{new ConfirmarPedidoComando(pedido,repo).ejecutar();throw new AssertionError("Debió fallar");}catch(IllegalArgumentException ok){}if(!"Pendiente".equals(pedido.getEstado()))throw new AssertionError("Memento no restauró estado");System.out.println("OK: Composite y Memento restauran el estado al fallar el repositorio");}
 static void jasper()throws Exception{try(InputStream in=VerificaRestaurante.class.getResourceAsStream("/restaurante/reportes/ventas.jrxml")){JasperReport r=JasperCompileManager.compileReport(in);Map<String,Object> par=new HashMap<>();par.put("DESDE",java.sql.Date.valueOf("2026-01-01"));par.put("HASTA",java.sql.Date.valueOf("2026-12-31"));Map<String,Object> row=new HashMap<>();row.put("id_pago",1);row.put("fecha_pago",Timestamp.valueOf("2026-10-01 12:00:00"));row.put("codigo","P001");row.put("metodo_pago","Efectivo");row.put("monto",new java.math.BigDecimal("10.00"));JasperPrint print=JasperFillManager.fillReport(r,par,new JRMapCollectionDataSource(Collections.singletonList(row)));byte[] pdf=JasperExportManager.exportReportToPdf(print);if(print.getPages().isEmpty()||pdf.length<100||pdf[0]!='%'||pdf[1]!='P')throw new AssertionError("Reporte PDF vacío");System.out.println("OK: JRXML compila, genera página y PDF en memoria con datos simulados");}}
 public static void main(String[] args)throws Exception{Class.forName("com.mysql.cj.jdbc.Driver");for(Enumeration<Driver>d=DriverManager.getDrivers();d.hasMoreElements();)DriverManager.deregisterDriver(d.nextElement());DriverManager.registerDriver(new DriverFalso());venta(false);venta(true);patrones();jasper();}
}

